from pathlib import Path

# Backend service: align single compressor fallback with the LRA-based refrigeration worksheet.
p=Path('portal/src/main/java/com/example/remoteportal/service/ElectricalCalculatorService.java')
s=p.read_text()
old='''  public Map<String,Object> refrigeration(double rla,Double mca,Double mocp,double cf,double oc,double of,String e){ok(e);pos(rla,"RLA");double ca=mca!=null&&mca>0?mca:rla*cf,op=mocp!=null&&mocp>0?mocp:rla*oc;Map<String,Object>r=b("REFRIGERATION",e);r.put("mcaProvided",mca!=null&&mca>0);r.put("mocpProvided",mocp!=null&&mocp>0);r.put("minimumCircuitAmpacityA",rd(ca));r.put("starterConductor",cond(ca));r.put("overloadWorksheetA",rd(rla*of));r.put("ocpdCalculatedA",rd(op));r.put("ocpdStandardA",mocp!=null&&mocp>0?notAbove(op):next(op));r.put("reference","CEC 2024 motor/refrigeration and air-conditioning rules; equipment nameplate MCA/MOCP values take priority where applicable");r.put("note","Final selection must follow the equipment nameplate and the refrigeration/air-conditioning rule applicable to the equipment.");return r;}\n'''
new='''  public Map<String,Object> refrigeration(double rla,Double lra,Double mca,Double mocp,double cf,double of,boolean failsToStart,String e){ok(e);pos(rla,"RLA");double locked=lra!=null&&lra>0?lra:rla*6.0;boolean markedMca=mca!=null&&mca>0,markedMocp=mocp!=null&&mocp>0;double ca=markedMca?mca:rla*cf;double derivedOcpd=locked*(failsToStart?0.65:0.50);double op=markedMocp?mocp:derivedOcpd;Map<String,Object>r=b("REFRIGERATION",e);r.put("rlaA",rd(rla));r.put("lraA",rd(locked));r.put("lraWasDerived",lra==null||lra<=0);r.put("motorFailsToStart",failsToStart);r.put("mcaProvided",markedMca);r.put("mocpProvided",markedMocp);r.put("minimumCircuitAmpacityA",rd(ca));r.put("starterConductor",cond(ca));r.put("overloadWorksheetA",rd(rla*of));r.put("ocpdCalculationBasis",markedMocp?"Equipment nameplate MOCP":(failsToStart?"65% of LRA failed-start maximum":"50% of LRA normal maximum"));r.put("ocpdCalculatedA",rd(op));r.put("ocpdStandardA",markedMocp?rd(op):Math.max(15,notAbove(op)));r.put("reference","CEC 2024 Rules 28-704, 28-706, 28-708 and 28-710; marked equipment MCA/MOCP values take priority where applicable");r.put("note",markedMca||markedMocp?"Marked equipment MCA/MOCP values are used where entered. Verify the equipment nameplate and manufacturer instructions.":"When no MOCP is marked, this worksheet uses the refrigerant motor-compressor LRA protection path: 50% LRA normally, or up to 65% LRA when the normal device will not permit starting. Blank LRA is derived as 6 × RLA for worksheet practice only.");return r;}\n'''
if old not in s: raise SystemExit('old refrigeration service method not found')
s=s.replace(old,new,1)
p.write_text(s)

# API resource request now accepts LRA and failed-start selection.
p=Path('portal/src/main/java/com/example/remoteportal/web/CalculatorResource.java')
s=p.read_text()
old='''  public record RefrigerationRequest(Double rla,Double mca,Double mocp,Double conductorFactor,Double ocpdFactor,Double overloadFactor,String edition){}\n  @PostMapping("/refrigeration") public Map<String,Object> refrigeration(@RequestBody RefrigerationRequest r){return calculators.refrigeration(n(r.rla()),r.mca(),r.mocp(),d(r.conductorFactor(),1.25),d(r.ocpdFactor(),1.75),d(r.overloadFactor(),1.15),edition(r.edition()));}\n'''
new='''  public record RefrigerationRequest(Double rla,Double lra,Double mca,Double mocp,Double conductorFactor,Double overloadFactor,Boolean motorFailsToStart,String edition){}\n  @PostMapping("/refrigeration") public Map<String,Object> refrigeration(@RequestBody RefrigerationRequest r){return calculators.refrigeration(n(r.rla()),r.lra(),r.mca(),r.mocp(),d(r.conductorFactor(),1.25),d(r.overloadFactor(),1.15),Boolean.TRUE.equals(r.motorFailsToStart()),edition(r.edition()));}\n'''
if old not in s: raise SystemExit('old refrigeration API block not found')
s=s.replace(old,new,1)
p.write_text(s)

